pub async fn credential_terminate(credentials: Rc<CredentialAcquisitionStore>, reference: String, expected: i64, verdict: Rc<AttemptVerdict>, detail: String, reader: Rc<CredentialReaderStanding>, filesystem: &Filesystem) -> std::result::Result<Rc<AttemptTransition>, std::boxed::Box<dyn std::error::Error>> {
    Ok(match (*credential_slot_observe(credentials.clone(), reference.clone(), filesystem).await?).clone() {
    CasSlotObservation::CasObservedUnreadable { cause: c, .. } => Rc::new(AttemptTransition::AttemptTransitionRefused {
    detail: Rc::new(vec!["the attempt slot could not be read: ".to_string(), crate::std_durable_compare_and_set::cas_unreadable_slot_detail(c.clone())]).join(&"".to_string()),
}),
    CasSlotObservation::CasObservedReadable { readable: r, .. } => match (*r.clone()).clone() {
    CasReadableSlot::CasReadableAbsent => Rc::new(AttemptTransition::AttemptLostRace {
    expected: Rc::new(vec!["generation ".to_string(), (crate::std_durable_compare_and_set::cas_generation_count(expected.clone())).to_string()]).join(&"".to_string()),
    observed: "an absent slot".to_string(),
}),
    CasReadableSlot::CasReadablePresent { version: v, .. } => match credential_record_decode(v.value.clone()) {
    std::option::Option::None => Rc::new(AttemptTransition::AttemptTransitionRefused {
    detail: "the credential slot holds a record this fold cannot decode".to_string(),
}),
    Some(rec) => match (*rec.state.clone()).clone() {
    AttemptState::AttemptLaunching => match (*reader.clone()).clone() {
    CredentialReaderStanding::CredentialReaderEnded => crate::gunbc_compute_attempt_lifecycle::attempt_terminate_payload(credentials.slots(), reference.clone(), expected.clone(), verdict.clone(), detail.clone(), credential_acquisition_codec(), filesystem).await?,
    CredentialReaderStanding::CredentialReaderRunning => Rc::new(AttemptTransition::AttemptTransitionRefused {
    detail: "Launching may only terminate after the launched reader has ended".to_string(),
}),
    CredentialReaderStanding::CredentialReaderUnobserved { detail: d, .. } => Rc::new(AttemptTransition::AttemptTransitionRefused {
    detail: Rc::new(vec!["Launching may only terminate after the launched reader has ended; reader unobserved: ".to_string(), d.clone()]).join(&"".to_string()),
}),
},
    AttemptState::AttemptReserved => crate::gunbc_compute_attempt_lifecycle::attempt_terminate_payload(credentials.slots(), reference.clone(), expected.clone(), verdict.clone(), detail.clone(), credential_acquisition_codec(), filesystem).await?,
    AttemptState::AttemptTerminal { .. } => crate::gunbc_compute_attempt_lifecycle::attempt_terminate_payload(credentials.slots(), reference.clone(), expected.clone(), verdict.clone(), detail.clone(), credential_acquisition_codec(), filesystem).await?,
},
},
},
})
}

pub async fn observe_self_control_group(filesystem: &Filesystem) -> std::result::Result<Option<String>, std::boxed::Box<dyn std::error::Error>> {
    let raw = filesystem.read(crate::extdeps_linux_procfs::procfs_path_literal(ProcfsPath::ProcSelfCgroup)).await?;
Ok(if raw.1.clone() {
        match (*crate::extdeps_linux_proc_self_cgroup::read_unified_cgroup_membership(raw.0.clone())).clone() {
    ProcPidCgroupMembershipRecord::CurrentCgroupObserved { relative_path: rel, .. } => Some(rel.clone()),
    ProcPidCgroupMembershipRecord::MembershipMissing => std::option::Option::None,
    ProcPidCgroupMembershipRecord::MembershipAmbiguous { .. } => std::option::Option::None,
    ProcPidCgroupMembershipRecord::MembershipMalformed { cause: _, .. } => std::option::Option::None,
}
    } else {
        std::option::Option::None
    })
}

pub fn belt_unit_from_control_group(control_group: String) -> String {
    Rc::new(control_group.clone().split(&"/".to_string()).map(|s| s.to_string()).collect::<Vec<_>>()).iter().cloned().fold("".to_string(), |acc: String, part: String| if (v1_rt::trim(part.clone()) == "".to_string()) {
        acc
    } else {
        v1_rt::trim(part.clone())
    })
}

