pub async fn credential_discard_taken_attempt(snapshot: Rc<TakenCredentialSnapshot>, shell_mktemp: &Shell__Mktemp, shell_remove: &Shell__Remove, filesystem: &Filesystem, shell_move: &Shell__Move, shell_id: &Shell__Id, shell_stat: &Shell__Stat, shell_test: &Shell__Test, shell_path: &Shell__Path, shell_exec: &Shell__Exec) -> std::result::Result<Rc<CredentialSnapshotDiscard>, std::boxed::Box<dyn std::error::Error>> {
    let tombstoned = crate::gunbc_dispatch_credential_snapshot::dispatch_credential_snapshot_discard(snapshot.clone(), shell_mktemp, shell_remove, filesystem, shell_move).await?;
let attempt = crate::gunbc_dispatch_credential_snapshot::taken_credential_snapshot_attempt(snapshot.clone());
let executor = crate::gunbc_dispatch_credential_snapshot::taken_credential_snapshot_executor(snapshot.clone());
let removed = match executor.clone() {
    SnapshotExecutor::ClaudeFromSnapshot => Rc::new(CredentialSealReceipt::CredentialSealed {
    path: "".to_string(),
}),
    SnapshotExecutor::CursorFromSnapshot => match (*credential_acquisition_store(attempt.instance.clone(), filesystem).await?).clone() {
    CredentialAcquisitionStoreReading::CredentialAcquisitionStoreUnready { detail: d, .. } => Rc::new(CredentialSealReceipt::CredentialSealFailed {
    detail: Rc::new(vec!["the credential store is not ready, so ownership of the cursor runtime root is unknown and it stays owed: ".to_string(), d.clone()]).join(&"".to_string()),
}),
    CredentialAcquisitionStoreReading::CredentialAcquisitionStoreReady { store: credentials, .. } => match credential_slot_record(credentials.clone(), credential_acquisition_reference(attempt.attempt_key.clone(), executor.clone()), filesystem).await? {
    std::option::Option::None => Rc::new(CredentialSealReceipt::CredentialSealFailed {
    detail: "the attempt record could not be read, so ownership of the cursor runtime root is unknown and it stays owed".to_string(),
}),
    Some(rec) => credential_retire_cursor_runtime_root(rec.clone(), credentials.clone(), filesystem, shell_id, shell_stat, shell_test, shell_path, shell_exec).await?,
},
},
};
Ok(match (*tombstoned.clone()).clone() {
    CredentialSnapshotDiscard::CredentialSnapshotTombstoneFailed { reason: r, .. } => Rc::new(CredentialSnapshotDiscard::CredentialSnapshotTombstoneFailed {
    reason: Rc::new(vec![r.clone(), credential_removal_owed_note(removed.clone())]).join(&"".to_string()),
}),
    CredentialSnapshotDiscard::CredentialSnapshotTombstoned => match (*removed.clone()).clone() {
    CredentialSealReceipt::CredentialSealFailed { detail: d, .. } => Rc::new(CredentialSnapshotDiscard::CredentialSnapshotTombstoneFailed {
    reason: d.clone(),
}),
    CredentialSealReceipt::CredentialSealed { path: _, .. } => Rc::new(CredentialSnapshotDiscard::CredentialSnapshotTombstoned),
    CredentialSealReceipt::CredentialCleanupOwed { reason: d, .. } => Rc::new(CredentialSnapshotDiscard::CredentialSnapshotTombstoneFailed {
    reason: d.clone(),
}),
},
})
}

pub async fn credential_discard_taken_snapshot(snapshot: Rc<TakenCredentialSnapshot>, shell_mktemp: &Shell__Mktemp, shell_remove: &Shell__Remove, filesystem: &Filesystem, shell_move: &Shell__Move, shell_id: &Shell__Id, shell_stat: &Shell__Stat, shell_test: &Shell__Test, shell_path: &Shell__Path, shell_exec: &Shell__Exec) -> std::result::Result<Rc<LaunchLostOutcome>, std::boxed::Box<dyn std::error::Error>> {
    Ok(match (*credential_discard_taken_attempt(snapshot, shell_mktemp, shell_remove, filesystem, shell_move, shell_id, shell_stat, shell_test, shell_path, shell_exec).await?).clone() {
    CredentialSnapshotDiscard::CredentialSnapshotTombstoned => Rc::new(LaunchLostOutcome::LaunchLostSnapshotDiscarded),
    CredentialSnapshotDiscard::CredentialSnapshotTombstoneFailed { reason: r, .. } => Rc::new(LaunchLostOutcome::LaunchLostDiscardFailed {
    reason: r.clone(),
}),
})
}

pub async fn credential_begin_launch_or_discard(credentials: Rc<CredentialAcquisitionStore>, reference: String, expected: i64, snapshot: Rc<TakenCredentialSnapshot>, filesystem: &Filesystem, shell_mktemp: &Shell__Mktemp, shell_remove: &Shell__Remove, shell_move: &Shell__Move, shell_id: &Shell__Id, shell_stat: &Shell__Stat, shell_test: &Shell__Test, shell_path: &Shell__Path, shell_exec: &Shell__Exec) -> std::result::Result<Rc<LaunchLostOutcome>, std::boxed::Box<dyn std::error::Error>> {
    Ok(match (*credential_begin_launch(credentials, reference, expected, filesystem).await?).clone() {
    AttemptTransition::AttemptAdvanced { .. } => Rc::new(LaunchLostOutcome::CredentialLaunchAdmitted),
    AttemptTransition::AttemptLostRace { .. } => credential_discard_taken_snapshot(snapshot.clone(), shell_mktemp, shell_remove, filesystem, shell_move, shell_id, shell_stat, shell_test, shell_path, shell_exec).await?,
    AttemptTransition::AttemptTransitionRefused { detail: _, .. } => credential_discard_taken_snapshot(snapshot.clone(), shell_mktemp, shell_remove, filesystem, shell_move, shell_id, shell_stat, shell_test, shell_path, shell_exec).await?,
})
}

pub async fn credential_admit_reader_or_discard(snapshot: Rc<TakenCredentialSnapshot>, filesystem: &Filesystem, shell_mktemp: &Shell__Mktemp, shell_remove: &Shell__Remove, shell_move: &Shell__Move, shell_id: &Shell__Id, shell_stat: &Shell__Stat, shell_test: &Shell__Test, shell_path: &Shell__Path, shell_exec: &Shell__Exec) -> std::result::Result<Rc<LaunchLostOutcome>, std::boxed::Box<dyn std::error::Error>> {
    let attempt = crate::gunbc_dispatch_credential_snapshot::taken_credential_snapshot_attempt(snapshot.clone());
let reference = credential_acquisition_reference(attempt.attempt_key.clone(), crate::gunbc_dispatch_credential_snapshot::taken_credential_snapshot_executor(snapshot.clone()));
Ok(match (*credential_acquisition_store(attempt.instance.clone(), filesystem).await?).clone() {
    CredentialAcquisitionStoreReading::CredentialAcquisitionStoreUnready { detail: _, .. } => credential_discard_taken_snapshot(snapshot.clone(), shell_mktemp, shell_remove, filesystem, shell_move, shell_id, shell_stat, shell_test, shell_path, shell_exec).await?,
    CredentialAcquisitionStoreReading::CredentialAcquisitionStoreReady { store: credentials, .. } => match (*credential_slot_observe(credentials.clone(), reference.clone(), filesystem).await?).clone() {
    CasSlotObservation::CasObservedUnreadable { cause: _, .. } => credential_discard_taken_snapshot(snapshot.clone(), shell_mktemp, shell_remove, filesystem, shell_move, shell_id, shell_stat, shell_test, shell_path, shell_exec).await?,
    CasSlotObservation::CasObservedReadable { readable: r, .. } => match (*r.clone()).clone() {
    CasReadableSlot::CasReadableAbsent => credential_discard_taken_snapshot(snapshot.clone(), shell_mktemp, shell_remove, filesystem, shell_move, shell_id, shell_stat, shell_test, shell_path, shell_exec).await?,
    CasReadableSlot::CasReadablePresent { version: v, .. } => match credential_record_decode(v.value.clone()) {
    std::option::Option::None => credential_discard_taken_snapshot(snapshot.clone(), shell_mktemp, shell_remove, filesystem, shell_move, shell_id, shell_stat, shell_test, shell_path, shell_exec).await?,
    Some(rec) => match (*rec.state.clone()).clone() {
    AttemptState::AttemptReserved => credential_begin_launch_or_discard(credentials.clone(), reference.clone(), crate::std_durable_compare_and_set::cas_generation_first(), snapshot.clone(), filesystem, shell_mktemp, shell_remove, shell_move, shell_id, shell_stat, shell_test, shell_path, shell_exec).await?,
    AttemptState::AttemptLaunching => credential_discard_taken_snapshot(snapshot.clone(), shell_mktemp, shell_remove, filesystem, shell_move, shell_id, shell_stat, shell_test, shell_path, shell_exec).await?,
    AttemptState::AttemptTerminal { .. } => credential_discard_taken_snapshot(snapshot.clone(), shell_mktemp, shell_remove, filesystem, shell_move, shell_id, shell_stat, shell_test, shell_path, shell_exec).await?,
},
},
},
},
})
}

