pub async fn credential_recover_slot(credentials: Rc<CredentialAcquisitionStore>, reference: String, now: i64, reader: Rc<CredentialReaderStanding>, filesystem: &Filesystem, shell_id: &Shell__Id, shell_stat: &Shell__Stat, shell_test: &Shell__Test, shell_path: &Shell__Path, shell_mktemp: &Shell__Mktemp, shell_remove: &Shell__Remove, shell_move: &Shell__Move, shell_exec: &Shell__Exec) -> std::result::Result<Rc<CredentialSlotRecovery>, std::boxed::Box<dyn std::error::Error>> {
    Ok(match (*credential_slot_observe(credentials.clone(), reference.clone(), filesystem).await?).clone() {
    CasSlotObservation::CasObservedUnreadable { cause: c, .. } => Rc::new(CredentialSlotRecovery::CredentialSlotKept {
    text: Rc::new(vec!["preserve unreadable ".to_string(), reference.clone(), ": ".to_string(), crate::std_durable_compare_and_set::cas_unreadable_slot_detail(c.clone())]).join(&"".to_string()),
}),
    CasSlotObservation::CasObservedReadable { readable: r, .. } => match (*r.clone()).clone() {
    CasReadableSlot::CasReadableAbsent => Rc::new(CredentialSlotRecovery::CredentialSlotKept {
    text: Rc::new(vec!["absent ".to_string(), reference.clone()]).join(&"".to_string()),
}),
    CasReadableSlot::CasReadablePresent { version: v, .. } => match credential_record_decode(v.value.clone()) {
    std::option::Option::None => Rc::new(CredentialSlotRecovery::CredentialSlotFailed {
    text: Rc::new(vec!["undecodable ".to_string(), reference.clone()]).join(&"".to_string()),
}),
    Some(rec) => {
        let drain = crate::gunbc_compute_recorded_cgroup_drain::recorded_cgroup_drain(crate::gunbc_compute_recorded_cgroup_drain::observe_recorded_cgroup_path(rec.control_group.clone(), filesystem).await?);
match (*credential_recovery_decide(rec.clone(), drain.clone(), now, reader.clone(), observe_cursor_runtime_root_fact(rec.clone(), credentials.clone(), filesystem, shell_id, shell_stat, shell_test, shell_path).await?, filesystem).await?).clone() {
    CredentialRecoveryDecision::CredentialRecoveryPreserve { reason: why, .. } => Rc::new(CredentialSlotRecovery::CredentialSlotKept {
    text: Rc::new(vec!["preserve ".to_string(), reference.clone(), ": ".to_string(), why.clone()]).join(&"".to_string()),
}),
    CredentialRecoveryDecision::CredentialRecoverySealNow { reason: why, .. } => match (*credential_seal_after_terminate(rec.clone(), drain.clone(), credentials.clone(), filesystem, shell_mktemp, shell_remove, shell_move, shell_id, shell_stat, shell_test, shell_path, shell_exec).await?).clone() {
    CredentialSealReceipt::CredentialSealed { path: p, .. } => Rc::new(CredentialSlotRecovery::CredentialSlotClosed {
    text: Rc::new(vec!["sealed ".to_string(), p.clone()]).join(&"".to_string()),
}),
    CredentialSealReceipt::CredentialSealFailed { detail: d, .. } => Rc::new(CredentialSlotRecovery::CredentialSlotFailed {
    text: Rc::new(vec!["seal failed ".to_string(), reference.clone(), ": ".to_string(), d.clone()]).join(&"".to_string()),
}),
    CredentialSealReceipt::CredentialCleanupOwed { reason: o, .. } => Rc::new(CredentialSlotRecovery::CredentialSlotKept {
    text: Rc::new(vec!["owed ".to_string(), reference.clone(), ": ".to_string(), why.clone(), "; ".to_string(), o.clone()]).join(&"".to_string()),
}),
},
    CredentialRecoveryDecision::CredentialRecoveryMayClose { reason: why, .. } => match (*credential_terminate(credentials.clone(), reference.clone(), v.generation.clone(), Rc::new(AttemptVerdict::AttemptRecovered), why.clone(), reader.clone(), filesystem).await?).clone() {
    AttemptTransition::AttemptLostRace { expected: e, observed: o, .. } => Rc::new(CredentialSlotRecovery::CredentialSlotKept {
    text: Rc::new(vec!["terminate lost ".to_string(), reference.clone(), ": ".to_string(), e.clone(), " vs ".to_string(), o.clone()]).join(&"".to_string()),
}),
    AttemptTransition::AttemptTransitionRefused { detail: d, .. } => Rc::new(CredentialSlotRecovery::CredentialSlotFailed {
    text: Rc::new(vec!["terminate refused ".to_string(), reference.clone(), ": ".to_string(), d.clone()]).join(&"".to_string()),
}),
    AttemptTransition::AttemptAdvanced { .. } => match (*credential_seal_after_terminate(rec.clone(), drain.clone(), credentials.clone(), filesystem, shell_mktemp, shell_remove, shell_move, shell_id, shell_stat, shell_test, shell_path, shell_exec).await?).clone() {
    CredentialSealReceipt::CredentialSealed { path: p, .. } => Rc::new(CredentialSlotRecovery::CredentialSlotClosed {
    text: Rc::new(vec!["sealed ".to_string(), p.clone()]).join(&"".to_string()),
}),
    CredentialSealReceipt::CredentialSealFailed { detail: d, .. } => Rc::new(CredentialSlotRecovery::CredentialSlotFailed {
    text: Rc::new(vec!["seal failed ".to_string(), reference.clone(), ": ".to_string(), d.clone()]).join(&"".to_string()),
}),
    CredentialSealReceipt::CredentialCleanupOwed { reason: o, .. } => Rc::new(CredentialSlotRecovery::CredentialSlotKept {
    text: Rc::new(vec!["owed ".to_string(), reference.clone(), ": ".to_string(), o.clone()]).join(&"".to_string()),
}),
},
},
}
},
},
},
})
}

