pub async fn credential_recover_root(credentials: Rc<CredentialAcquisitionStore>, now: i64, reader_for: impl Fn(Rc<CredentialAcquisitionRecord>) -> Rc<CredentialReaderStanding> + Clone, filesystem: &Filesystem, shell_id: &Shell__Id, shell_stat: &Shell__Stat, shell_test: &Shell__Test, shell_path: &Shell__Path, shell_mktemp: &Shell__Mktemp, shell_remove: &Shell__Remove, shell_move: &Shell__Move, shell_exec: &Shell__Exec) -> std::result::Result<Rc<CredentialRootRecovery>, std::boxed::Box<dyn std::error::Error>> {
    Ok(match (*credential_slot_keys(credentials.clone(), filesystem).await?).clone() {
    CasSlotKeys::CasSlotKeysSubjectRefused { cause: c, .. } => Rc::new(CredentialRootRecovery::CredentialRootFailed {
    report: Rc::new(vec!["credential slot root refused: ".to_string(), c.clone()]).join(&"".to_string()),
}),
    CasSlotKeys::CasSlotKeysAbsent { root: r, .. } => Rc::new(CredentialRootRecovery::CredentialRootFailed {
    report: Rc::new(vec!["credential slot root is not present at ".to_string(), r.clone(), " -- an absent store is not an empty one, so no credential is reported recovered".to_string()]).join(&"".to_string()),
}),
    CasSlotKeys::CasSlotKeysListingRefused { detail: d, .. } => Rc::new(CredentialRootRecovery::CredentialRootFailed {
    report: Rc::new(vec!["credential slot listing refused: ".to_string(), d.clone()]).join(&"".to_string()),
}),
    CasSlotKeys::CasSlotKeysListed { keys: keys, .. } => if ((keys.clone().len() as i64) == 0) {
        Rc::new(CredentialRootRecovery::CredentialRootOk {
    report: "no credential slots".to_string(),
})
    } else {
        {
            let rows = Rc::new({ let mut __result = Vec::new(); for k in keys.iter().cloned() { __result.push(match (*credential_slot_observe(credentials.clone(), k.clone(), filesystem).await?).clone() {
    CasSlotObservation::CasObservedUnreadable { cause: c, .. } => Rc::new(CredentialSlotRecovery::CredentialSlotKept {
    text: Rc::new(vec!["preserve unreadable ".to_string(), k.clone(), ": ".to_string(), crate::std_durable_compare_and_set::cas_unreadable_slot_detail(c.clone())]).join(&"".to_string()),
}),
    CasSlotObservation::CasObservedReadable { readable: r, .. } => match (*r.clone()).clone() {
    CasReadableSlot::CasReadableAbsent => credential_recover_slot(credentials.clone(), k.clone(), now.clone(), Rc::new(CredentialReaderStanding::CredentialReaderUnobserved {
    detail: "absent while listing".to_string(),
}), filesystem, shell_id, shell_stat, shell_test, shell_path, shell_mktemp, shell_remove, shell_move, shell_exec).await?,
    CasReadableSlot::CasReadablePresent { version: v, .. } => match credential_record_decode(v.value.clone()) {
    std::option::Option::None => credential_recover_slot(credentials.clone(), k.clone(), now.clone(), Rc::new(CredentialReaderStanding::CredentialReaderUnobserved {
    detail: "undecodable".to_string(),
}), filesystem, shell_id, shell_stat, shell_test, shell_path, shell_mktemp, shell_remove, shell_move, shell_exec).await?,
    Some(rec) => credential_recover_slot(credentials.clone(), k.clone(), now.clone(), reader_for(rec.clone()), filesystem, shell_id, shell_stat, shell_test, shell_path, shell_mktemp, shell_remove, shell_move, shell_exec).await?,
},
},
}); } __result });
let report = Rc::new({ let mut __result = Vec::new(); for r in rows.iter().cloned() { __result.push(credential_slot_recovery_text(r.clone())); } __result }).join(&"\n".to_string());
let failed = rows.iter().cloned().fold(false, |acc: bool, row: Rc<CredentialSlotRecovery>| (acc || match (*row.clone()).clone() {
    CredentialSlotRecovery::CredentialSlotFailed { text: _, .. } => true,
    CredentialSlotRecovery::CredentialSlotKept { text: _, .. } => false,
    CredentialSlotRecovery::CredentialSlotClosed { text: _, .. } => false,
}));
if failed.clone() {
                Rc::new(CredentialRootRecovery::CredentialRootFailed {
    report: report.clone(),
})
            } else {
                Rc::new(CredentialRootRecovery::CredentialRootOk {
    report: report.clone(),
})
            }
}
    },
})
}

pub async fn credential_register_then_take(attempt: Rc<DispatchAttempt>, executor: SnapshotExecutor, custody: Rc<SnapshotCustodyDeclaration>, snapshot: String, clock: &Clock, filesystem: &Filesystem, shell_id: &Shell__Id, shell_stat: &Shell__Stat, shell_test: &Shell__Test, shell_path: &Shell__Path, shell_exec: &Shell__Exec, stat_file: &Stat__File) -> std::result::Result<Rc<DispatchCredentialSnapshot>, std::boxed::Box<dyn std::error::Error>> {
    Ok(match crate::gunbc_fabric_fabric_event_log_host::now_epoch_seconds(clock).await? {
    std::option::Option::None => Rc::new(DispatchCredentialSnapshot::DispatchSnapshotRefused {
    reason: Rc::new(DispatchSnapshotRefusal::SnapshotWriteFailed {
    path: snapshot.clone(),
    detail: "the host clock could not be read".to_string(),
}),
}),
    Some(now) => match (*observe_producer_identity(filesystem).await?).clone() {
    ProducerIdentity::ProducerUnidentified { detail: d, .. } => Rc::new(DispatchCredentialSnapshot::DispatchSnapshotRefused {
    reason: Rc::new(DispatchSnapshotRefusal::SnapshotWriteFailed {
    path: snapshot.clone(),
    detail: d.clone(),
}),
}),
    ProducerIdentity::ProducerIdentified { control_group: cg, belt_unit: unit, .. } => {
        let record = Rc::new(CredentialAcquisitionRecord {
    identity: attempt.attempt_key.clone(),
    node_id: attempt.node.node.clone(),
    reference: credential_acquisition_reference(attempt.attempt_key.clone(), executor.clone()),
    executor: credential_attempt_executor_for(executor.clone()),
    snapshot_path: snapshot.clone(),
    belt_unit: unit.clone(),
    control_group: cg.clone(),
    opened_at: now.clone(),
    launch_deadline: compile_error!("operator realization: host operator `+` on an operand whose declaration could not be read (authored `Int`, connective NoConnective, children 0, resolved no, provenance declared in `dag/std/types.dag`)"),
    state: Rc::new(AttemptState::AttemptReserved),
});
match (*credential_acquisition_store(attempt.instance.clone(), filesystem).await?).clone() {
    CredentialAcquisitionStoreReading::CredentialAcquisitionStoreUnready { detail: d, .. } => Rc::new(DispatchCredentialSnapshot::DispatchSnapshotRefused {
    reason: Rc::new(DispatchSnapshotRefusal::SnapshotWriteFailed {
    path: snapshot.clone(),
    detail: d.clone(),
}),
}),
    CredentialAcquisitionStoreReading::CredentialAcquisitionStoreReady { store: credentials, .. } => match (*credential_open(credentials.clone(), record.clone(), filesystem).await?).clone() {
    AttemptTransition::AttemptLostRace { expected: e, observed: o, .. } => Rc::new(DispatchCredentialSnapshot::DispatchSnapshotRefused {
    reason: Rc::new(DispatchSnapshotRefusal::SnapshotWriteFailed {
    path: snapshot.clone(),
    detail: Rc::new(vec!["credential open lost: expected ".to_string(), e.clone(), " found ".to_string(), o.clone()]).join(&"".to_string()),
}),
}),
    AttemptTransition::AttemptTransitionRefused { detail: d, .. } => Rc::new(DispatchCredentialSnapshot::DispatchSnapshotRefused {
    reason: Rc::new(DispatchSnapshotRefusal::SnapshotWriteFailed {
    path: snapshot.clone(),
    detail: d.clone(),
}),
}),
    AttemptTransition::AttemptAdvanced { .. } => match (*credential_create_cursor_runtime_root(record.clone(), credentials.clone(), shell_id, shell_stat, shell_test, shell_path, shell_exec, filesystem).await?).clone() {
    CursorRuntimeRootCreation::CursorRuntimeRootCreationRefused { detail: d, .. } => Rc::new(DispatchCredentialSnapshot::DispatchSnapshotRefused {
    reason: Rc::new(DispatchSnapshotRefusal::SnapshotWriteFailed {
    path: snapshot.clone(),
    detail: d.clone(),
}),
}),
    CursorRuntimeRootCreation::CursorRuntimeRootCreated => match (*crate::gunbc_dispatch_credential_snapshot::dispatch_credential_snapshot_take(attempt.clone(), executor.clone(), custody, snapshot.clone(), filesystem, shell_stat, stat_file, shell_exec).await?).clone() {
    DispatchCredentialSnapshot::DispatchSnapshotTaken { snapshot: taken, .. } => Rc::new(DispatchCredentialSnapshot::DispatchSnapshotTaken {
    snapshot: taken.clone(),
}),
    DispatchCredentialSnapshot::DispatchSnapshotRefused { reason: refusal, .. } => {
            let removed = credential_retire_cursor_runtime_root(record.clone(), credentials.clone(), filesystem, shell_id, shell_stat, shell_test, shell_path, shell_exec).await?;
match (*removed.clone()).clone() {
    CredentialSealReceipt::CredentialSealed { path: _, .. } => Rc::new(DispatchCredentialSnapshot::DispatchSnapshotRefused {
    reason: refusal.clone(),
}),
    CredentialSealReceipt::CredentialSealFailed { detail: _, .. } => Rc::new(DispatchCredentialSnapshot::DispatchSnapshotRefused {
    reason: Rc::new(DispatchSnapshotRefusal::SnapshotWriteFailed {
    path: snapshot.clone(),
    detail: Rc::new(vec![crate::gunbc_dispatch_credential_snapshot::dispatch_snapshot_refusal_text(refusal.clone()), credential_removal_owed_note(removed.clone())]).join(&"".to_string()),
}),
}),
    CredentialSealReceipt::CredentialCleanupOwed { reason: _, .. } => Rc::new(DispatchCredentialSnapshot::DispatchSnapshotRefused {
    reason: Rc::new(DispatchSnapshotRefusal::SnapshotWriteFailed {
    path: snapshot.clone(),
    detail: Rc::new(vec![crate::gunbc_dispatch_credential_snapshot::dispatch_snapshot_refusal_text(refusal.clone()), credential_removal_owed_note(removed.clone())]).join(&"".to_string()),
}),
}),
}
},
},
},
},
}
},
},
})
}

